FavoritePromptsPanel: FC<FavoritePromptsPanelProps> = ({
  favorites,
  onSelect,
  onToggleFavorite,
  onBrowse,
  labels = {},
  colors,
  nameClassName = 'dial-small-text',
  headerClassName = 'dial-tiny-lead-semi-text',
  emptyHintClassName = 'dial-small-text',
}) => {
  const {
    myCollectionLabel = 'My Collection',
    emptyHintLabel = 'Star a prompt to pin it here',
    browseLabel = 'Browse',
    removeFromFavoritesLabel = 'Remove from favorites',
  } = labels;

  const cssVars = buildCssVars({
    '--fp-header-text': colors?.headerText,
    '--fp-empty-hint-text': colors?.emptyHintText,
    '--fp-star-color': colors?.starColor,
    '--fp-footer-border': colors?.footerBorder,
  });

  const [leavingIds, setLeavingIds] = useState<Set<string>>(new Set());
  const leaveTimeoutsRef = useRef(
    new Map<string, ReturnType<typeof setTimeout>>(),
  );

  useEffect(() => {
    const timeouts = leaveTimeoutsRef.current;
    return () => {
      timeouts.forEach((timeout) => clearTimeout(timeout));
      timeouts.clear();
    };
  }, []);

  /*
   * Animates the scrollable list's own height as rows leave instead of
   * letting it snap instantly, since CSS can't transition height: auto.
   */
  const listContentRef = useRef<HTMLDivElement>(null);
  const [listHeight, setListHeight] = useState<number>();

  useLayoutEffect(() => {
    if (listContentRef.current) {
      setListHeight(
        Math.min(
          listContentRef.current.scrollHeight,
          SELECT_LIST_MAX_HEIGHT_PX,
        ),
      );
    }
  }, [favorites]);

  /*
   * Plays the row's fade-out animation before actually committing the
   * favorite change, since applying it immediately would make the row
   * (and its own animation) disappear instantly.
   */
  const handleToggleFavorite = (id: string) => {
    setLeavingIds((prev) => new Set(prev).add(id));
    const timeout = setTimeout(() => {
      onToggleFavorite(id);
      setLeavingIds((prev) => {
        const next = new Set(prev);
        next.delete(id);
        return next;
      });
      leaveTimeoutsRef.current.delete(id);
    }, ROW_LEAVE_ANIMATION_MS);
    leaveTimeoutsRef.current.set(id, timeout);
  };

  const renderRow = (item: FavoritePromptItem) => {
    const row = (
      /*
        The kit's own select-list row, so its rest, hover and focus states come
        from the design's list-item spec. The star goes through `rightControl`:
        it is a button, and a button nested inside the row's own button would be
        invalid markup, swallow the row's click, and land inside the row's
        accessible name.
      */
      <MenuItem
        className="h-auto py-1.5"
        icon={
          <DeploymentIcon size={DIAL_ICON_SIZE.MD} initialsName={item.name} />
        }
        label={item.name}
        labelClassName={nameClassName}
        onClick={() => onSelect(item)}
        /* `MenuItem` is a real button, so it needs no custom keydown handling for Enter/Space. */
        rightControl={
          <ToggleIconButton
            icon={
              <IconStarFilled
                size={DIAL_ICON_SIZE.SM}
                className={styles.star}
                aria-hidden
              />
            }
            aria-label={removeFromFavoritesLabel}
            /* Every row in this panel is a favorite, so the star is always on. */
            isSelected
            onClick={() => handleToggleFavorite(item.id)}
          />
        }
      />
    );

    const hasDescription = item.description != null && item.description !== '';

    return (
      <li
        key={item.id}
        className={
          leavingIds.has(item.id) ? styles.rowLeaving : styles.rowEnter
        }
      >
        {hasDescription ? (
          /*
           * The row stays the focus/click target (`asChild`); the tooltip is
           * uncontrolled — the kit opens it on hover or keyboard focus and
           * keeps it open while the pointer travels between the row and the
           * panel — and renders nothing on touch-only devices, where tapping
           * the row still inserts the prompt. Rows without a description are
           * not wrapped at all.
           */
          <InteractiveTooltip
            asChild
            contentClassName="max-w-[550px]"
            content={<p className="text-start">{item.description}</p>}
          >
            {row}
          </InteractiveTooltip>
        ) : (
          row
        )}
      </li>
    );
  };

  return (
    <div
      className={mergeClasses(
        'flex min-w-[240px] flex-col',
        PROMPTS_CLASS.favoritesPanel,
      )}
      style={cssVars}
    >
      <p
        className={mergeClasses(
          headerClassName,
          SECTION_HEADING_CLASS_NAME,
          styles.header,
        )}
      >
        {myCollectionLabel}
      </p>

      <div
        className={mergeClasses(
          SELECT_LIST_MAX_HEIGHT_CLASS_NAME,
          'min-h-0 flex-1 overflow-y-auto',
          styles.listContent,
        )}
        style={{ maxHeight: listHeight }}
      >
        <div ref={listContentRef}>
          {favorites.length > 0 ? (
            <ul className="flex flex-col gap-1 px-1 pb-1">
              {favorites.map(renderRow)}
            </ul>
          ) : (
            <p
              className={mergeClasses(
                emptyHintClassName,
                'px-4 py-4 text-start',
                styles.emptyHint,
              )}
            >
              {emptyHintLabel}
            </p>
          )}
        </div>
      </div>

      <div className={mergeClasses('border-t px-2 py-3', styles.footer)}>
        <GhostButton
          label={browseLabel}
          className="w-full justify-center"
          onClick={onBrowse}
        />
      </div>
    </div>
  );
}

PromptParametersPopup: FC<PromptParametersPopupProps> = ({
  open,
  promptName,
  content,
  description,
  parameters,
  onBack,
  onClose,
  onSubmit,
  onCancel,
  labels = {},
  colors,
  titleClassName = 'dial-h2-text',
  parametersLabelClassName = 'dial-h2-text',
  detailsLabelClassName = 'dial-h2-text',
}) => {
  const {
    title = 'Prompt parameters',
    closeLabel = 'Close',
    backLabel = 'Back',
    parametersLabel = 'Parameters',
    detailsLabel = 'Details',
    enterValuePlaceholder = 'Enter value',
    cancelLabel = 'Cancel',
    submitLabel = 'Confirm',
  } = labels;

  const parametersKey = parameters
    .map(({ name, defaultValue }) => `${name}\u0000${defaultValue ?? ''}`)
    .join('\u0001');

  const [values, setValues] = useState<Record<string, string>>(() =>
    buildPromptParamDefaults(parameters),
  );
  const [seededKey, setSeededKey] = useState(parametersKey);

  /*
   * Re-seed during render (React's "adjust state when a prop changes") when the
   * popup is handed a different set of parameters, so reopening a prompt offers
   * its defaults again rather than whatever was typed the previous time.
   */
  if (seededKey !== parametersKey) {
    setSeededKey(parametersKey);
    setValues(buildPromptParamDefaults(parameters));
  }

  const fieldIdPrefix = useId();

  const cssVars = buildCssVars({
    '--pp-card-bg': colors?.cardBackground,
    '--pp-card-border': colors?.cardBorder,
  });

  const isSubmitDisabled = parameters.some(({ name }) => !values[name]?.trim());

  const handleSubmit = () => {
    if (isSubmitDisabled) return;
    onSubmit(values);
  };

  const header = (
    <div className="flex items-center gap-2">
      {onBack != null && (
        <GhostIconButton
          icon={
            <IconChevronLeft
              className="rtl:scale-x-[-1]"
              aria-hidden
              stroke={DIAL_KIT_ICON_STROKE}
            />
          }
          aria-label={backLabel}
          onClick={onBack}
        />
      )}
      <span className={titleClassName}>{title}</span>
    </div>
  );

  return (
    <Popup
      open={open}
      header={header}
      ariaLabel={title}
      size={PopupSize.Lg}
      closeAriaLabel={closeLabel}
      onClose={onClose}
      footer={
        <div className="flex justify-end gap-2 px-6 py-4">
          <NeutralButton label={cancelLabel} onClick={onCancel} />
          <PrimaryButton
            label={submitLabel}
            disabled={isSubmitDisabled}
            onClick={handleSubmit}
          />
        </div>
      }
    >
      <div className="flex flex-col gap-4 px-6 pb-4 pt-2">
        <div
          className={mergeClasses(
            'flex h-[72px] w-full items-center rounded-lg border px-3',
            styles.card,
          )}
          style={cssVars}
        >
          <AppIdentity
            type={CatalogEntityType.Prompt}
            name={promptName}
            size={DeploymentSize.LG}
            className="w-full"
          />
        </div>

        <div className="grid grid-cols-2 gap-4">
          <div className="flex flex-col gap-3">
            <h2 className={mergeClasses(parametersLabelClassName, 'm-0')}>
              {parametersLabel}
            </h2>
            {parameters.map(({ name }) => {
              const fieldId = `${fieldIdPrefix}-${name}`;
              return (
                <Textarea
                  key={name}
                  id={fieldId}
                  aria-label={name}
                  value={values[name] ?? ''}
                  labelProps={{ htmlFor: fieldId, label: name, required: true }}
                  placeholder={enterValuePlaceholder}
                  onChange={(value) =>
                    setValues((prev) => ({ ...prev, [name]: value }))
                  }
                />
              );
            })}
          </div>

          <div className="flex min-h-0 flex-col gap-3">
            <h2 className={mergeClasses(detailsLabelClassName, 'm-0')}>
              {detailsLabel}
            </h2>
            <ContentTab content={content} description={description} />
          </div>
        </div>
      </div>
    </Popup>
  );
}

export interface FavoritePromptItem {
  /** Stable identifier for the prompt. */
  id: string;
  /** Display name. */
  name: string;
  /** Short description shown in a tooltip on hover. Omitted when empty. */
  description?: string;
  /** Full prompt body, including any `{{param}}` tokens. */
  content: string;
}

export interface FavoritePromptsPanelColors {
  /** Text color of the "My Collection" header. Defaults to `--text-tertiary`. */
  headerText?: string;
  /** Text color of the empty-favorites hint. Defaults to `--text-icon-tertiary`. */
  emptyHintText?: string;
  /** Fill color of a row's star icon. Defaults to `--text-warning-icon`. */
  starColor?: string;
  /** Border color above the footer's Browse button. Defaults to `--stroke-tertiary`. */
  footerBorder?: string;
}

export interface FavoritePromptsPanelLabels {
  /** Header above the favorites list. Defaults to `'My Collection'`. */
  myCollectionLabel?: string;
  /** Hint shown when there are no favorites. Defaults to `'Star a prompt to pin it here'`. */
  emptyHintLabel?: string;
  /** Label for the footer action button. Defaults to `'Browse'`. */
  browseLabel?: string;
  /** Accessible label for a row's remove-from-favorites star button. Defaults to `'Remove from favorites'`. */
  removeFromFavoritesLabel?: string;
}

export interface FavoritePromptsPanelProps {
  /** The user's favorited prompts, already resolved by the host. */
  favorites: FavoritePromptItem[];
  /** Called when a row is activated (click, Enter, or Space). */
  onSelect: (item: FavoritePromptItem) => void;
  /** Called with a prompt's id when its row's star button is clicked to remove it from favorites. */
  onToggleFavorite: (id: string) => void;
  /** Called when the "Browse" button is clicked. */
  onBrowse: () => void;
  /** Localizable string overrides. */
  labels?: FavoritePromptsPanelLabels;
  /** Color overrides applied as CSS custom properties. */
  colors?: FavoritePromptsPanelColors;
  /** CSS class applied to a row's prompt name. Defaults to `'dial-small-text'`. */
  nameClassName?: string;
  /** CSS class applied to the "My Collection" header. Defaults to `'dial-tiny-lead-semi-text'`, which uppercases the label itself. */
  headerClassName?: string;
  /** CSS class applied to the empty-favorites hint. Defaults to `'dial-small-text'`. */
  emptyHintClassName?: string;
}

export interface PromptParametersPopupColors {
  /** Background color of the prompt summary card. Defaults to `--bg-layer-sunken`. */
  cardBackground?: string;
  /** Border color of the prompt summary card. Defaults to `--stroke-tertiary`. */
  cardBorder?: string;
}

export interface PromptParametersPopupLabels {
  /** Dialog title. Defaults to `'Prompt parameters'`. */
  title?: string;
  /** Accessible label for the close button. Defaults to `'Close'`. */
  closeLabel?: string;
  /** Accessible label for the back chevron, shown only when `onBack` is provided. Defaults to `'Back'`. */
  backLabel?: string;
  /** Heading for the parameters column. Defaults to `'Parameters'`. */
  parametersLabel?: string;
  /** Heading for the details column. Defaults to `'Details'`. */
  detailsLabel?: string;
  /** Placeholder shown in each empty parameter field. Defaults to `'Enter value'`. */
  enterValuePlaceholder?: string;
  /** Label for the footer Cancel button. Defaults to `'Cancel'`. */
  cancelLabel?: string;
  /** Label for the footer Submit button. Defaults to `'Confirm'`. */
  submitLabel?: string;
}

export interface PromptParametersPopupProps {
  /** Whether the popup is open. */
  open: boolean;
  /** The selected prompt's display name, shown in the summary card. */
  promptName: string;
  /** The selected prompt's full content, including `{{param}}` tokens — rendered read-only in the Details column. */
  content: string;
  /** Short summary shown above the divider in the Details column. Omitted when empty. */
  description?: string;
  /**
   * Distinct parameters found in `content`, in first-occurrence order — as
   * returned by `extractPromptParams`. One required field is rendered per
   * entry, labelled with the parameter's name and starting out holding its
   * `defaultValue` when it has one.
   */
  parameters: PromptParameter[];
  /**
   * Called to return to the previous screen (the browse modal). When omitted,
   * no back chevron is rendered — the popup was opened directly from a favorite.
   */
  onBack?: () => void;
  /** Called when the popup is dismissed via the close button. */
  onClose: () => void;
  /** Called with the entered values, keyed by parameter name, when Submit is clicked. */
  onSubmit: (values: Record<string, string>) => void;
  /** Called when the Cancel button is clicked. */
  onCancel: () => void;
  /** Localizable string overrides. */
  labels?: PromptParametersPopupLabels;
  /** Color overrides applied as CSS custom properties. */
  colors?: PromptParametersPopupColors;
  /** CSS class applied to the popup title. Defaults to `'dial-h2-text'`. */
  titleClassName?: string;
  /** CSS class applied to the "Parameters" column heading. Defaults to `'dial-h2-text'`. */
  parametersLabelClassName?: string;
  /** CSS class applied to the "Details" column heading. Defaults to `'dial-h2-text'`. */
  detailsLabelClassName?: string;
}

PROMPTS_CLASS = {
  /** The favorite-prompts panel root, which carries the themed CSS variables. */
  favoritesPanel: 'dial-prompts-favorites-panel',
} as const

